#include <bits/stdc++.h>
using namespace std;

struct MaxFlow {
    struct Edge {
        int from, to;
        long long flow, capacity;
    };
    int s, t;
    vector<Edge> edges;
    vector<int> graph[7100];
    int dist[7100], visited[7100], current[7100];

    void initialize() {
        edges.clear();
        for (int i = 0; i < 7100; ++i) {
            graph[i].clear();
        }
    }

    void addEdge(int from, int to, long long cap) {
        Edge e1 = {from, to, 0, cap};
        Edge e2 = {to, from, 0, 0};
        edges.push_back(e1);
        edges.push_back(e2);
        graph[from].push_back((int)edges.size() - 2);
        graph[to].push_back((int)edges.size() - 1);
    }

    bool buildLevelGraph() {
        memset(visited, 0, sizeof(visited));
        memset(dist, 0, sizeof(dist));
        queue<int> q;
        q.push(s);
        visited[s] = 1;
        dist[s] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int i = 0; i < (int)graph[v].size(); ++i) {
                auto &e = edges[graph[v][i]];
                int nxt = e.to;
                if (!visited[nxt] && e.capacity > e.flow) {
                    dist[nxt] = dist[v] + 1;
                    q.push(nxt);
                    visited[nxt] = 1;
                }
            }
        }
        return visited[t];
    }

    long long sendFlow(int u, long long flow) {
        if (u == t || flow == 0) return flow;
        long long totalFlow = 0;
        for (int &i = current[u]; i < (int)graph[u].size(); ++i) {
            auto &e = edges[graph[u][i]];
            if (dist[u] + 1 == dist[e.to]) {
                long long pushed = sendFlow(e.to, min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[graph[u][i] ^ 1].flow -= pushed;
                    totalFlow += pushed;
                    flow -= pushed;
                    if (flow == 0) break;
                }
            }
        }
        return totalFlow;
    }

    long long maxFlow() {
        long long total = 0;
        while (buildLevelGraph()) {
            for (int i = 0; i < 7100; ++i) current[i] = 0;
            total += sendFlow(s, LLONG_MAX);
        }
        return total;
    }
};

MaxFlow mf;
char grid1[14][14], grid2[14][14];
bool visitedCells[14][14];
int distanceMap[14][14];
int n;
int target[103];

void performBFS(int x, int y) {
    std::queue<std::pair<std::pair<int, int>, int>> q;
    for (int i = 0; i < 14; ++i)
        for (int j = 0; j < 14; ++j)
            distanceMap[i][j] = 111;
    distanceMap[x][y] = 0;
    q.push({{x, y}, 0});
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int cx = p.first.first, cy = p.first.second, distVal = p.second;
        if (visitedCells[cx][cy]) continue;
        visitedCells[cx][cy] = true;
        distanceMap[cx][cy] = distVal;
        for (int dir = 0; dir < 4; ++dir) {
            int nx = cx + dx[dir], ny = cy + dy[dir];
            if (nx <= 0 || nx > n || ny <= 0 || ny > n || visitedCells[nx][ny] || grid1[nx][ny] == 'Y') continue;
            q.push({{nx, ny}, distVal + 1});
        }
    }
}

int getIndex(int level, int x, int y) {
    return level * n * n + (x - 1) * n + y;
}

int main() {
    int t, i, j, k;
    scanf("%d%d", &n, &t);
    for (i = 1; i <= n; ++i) scanf("%s", grid1[i] + 1);
    for (i = 1; i <= n; ++i) scanf("%s", grid2[i] + 1);
    mf.s = 0; mf.t = 7099;
    int startX = 0, startY = 0;
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') {
                startX = i; startY = j; break;
            }
        }
    }
    for (i = 1; i <= n * n; ++i) target[i] = 7098 - (n * n - i);
    performBFS(startX, startY);
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= n; ++j) {
            if (grid1[i][j] >= '0' && grid1[i][j] <= '9')
                mf.addEdge(mf.s, getIndex(0, i, j), grid1[i][j] - '0');
            if (grid2[i][j] >= '0' && grid2[i][j] <= '9')
                mf.addEdge(target[getIndex(0, i, j)], mf.t, grid2[i][j] - '0');
            mf.addEdge(getIndex(0, i, j), target[getIndex(0, i, j)], LLONG_MAX);
        }
    }
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    for (i = 1; i <= t; ++i) {
        for (j = 1; j <= n; ++j) {
            for (k = 1; k <= n; ++k) {
                if (grid1[j][k] == 'Y' || grid1[j][k] == 'Z') continue;
                for (int l = 0; l < 4; ++l) {
                    int tx = j + dx[l], ty = k + dy[l];
                    if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && grid1[tx][ty] != 'Y' && grid1[tx][ty] != 'Z') {
                        if (distanceMap[j][k] >= i && distanceMap[tx][ty] >= i) {
                            mf.addEdge(getIndex(i - 1, tx, ty), getIndex(i, j, k), LLONG_MAX);
                        }
                    }
                }
                mf.addEdge(getIndex(i, j, k), target[getIndex(0, j, k)], LLONG_MAX);
            }
        }
    }
    printf("%lld\n", mf.maxFlow());
    return 0;
}
